"""Quota-constrained follow-up planning.

An assignment sends one unit of obligation from a source, down the request
quota forest, through the request, across an allowed request/offer pair (whose
cost is the offer cost), up the offer quota forest and into a sink.  Tree arcs
carry the node capacities, so a unit consumes one slot at its group and at
every ancestor of both forests; request arcs cap at one and offer arcs at the
offer capacity.  A successive-shortest-path search with potentials therefore
returns a maximum-cardinality plan of minimum total offer cost.

When both quota forests are provably non-binding (every node capacity is at
least the largest flow its subtree could ever carry) the forest arcs cannot
constrain anything, and the remaining structure is a transversal matroid on
offer slots: greedy over offers in increasing cost with augmenting-path
independence tests yields the same optimum much faster.  Both routes are
exercised by the development test suite and agree on every instance where both
apply.
"""
from heapq import heappop, heappush
import sys

from protocols import CERTIFICATES

INFINITY = 1 << 62
DEPTH_LIMIT = 32

if sys.getrecursionlimit() < 20000:
    sys.setrecursionlimit(20000)


class Network:
    """Residual network stored as flat parallel arrays."""

    __slots__ = ('graph', 'to', 'cap', 'cost')

    def __init__(self, size):
        self.graph = [[] for _ in range(size)]
        self.to = []
        self.cap = []
        self.cost = []

    def add(self, tail, head, capacity, cost):
        graph = self.graph
        index = len(self.to)
        graph[tail].append(index)
        self.to.append(head)
        self.cap.append(capacity)
        self.cost.append(cost)
        graph[head].append(index + 1)
        self.to.append(tail)
        self.cap.append(0)
        self.cost.append(-cost)
        return index


def _augment_path(graph, to, cap, cost, dual, level, cursor, node, sink, limit):
    """Push one zero-reduced-cost path; Dinic iterators persist within a phase."""
    if node == sink:
        return limit
    edges = graph[node]
    index = cursor[node]
    depth = level[node] + 1
    base = dual[node]
    while index < len(edges):
        edge = edges[index]
        head = to[edge]
        if (cap[edge] > 0 and level[head] == depth
                and cost[edge] + base - dual[head] == 0):
            pushed = _augment_path(graph, to, cap, cost, dual, level, cursor,
                                   head, sink,
                                   limit if limit < cap[edge] else cap[edge])
            if pushed:
                cap[edge] -= pushed
                cap[edge ^ 1] += pushed
                cursor[node] = index
                return pushed
        index += 1
    cursor[node] = index
    return 0


def min_cost_flow(net, source, sink):
    """Maximum flow of minimum cost; returns ``(units, cost)``."""
    graph = net.graph
    to = net.to
    cap = net.cap
    cost = net.cost
    size = len(graph)
    dual = [0] * size
    units = 0
    spent = 0
    if source == sink:
        return 0, 0
    while True:
        dist = [INFINITY] * size
        dist[source] = 0
        heap = [(0, source)]
        while heap:
            distance, node = heappop(heap)
            if distance > dist[node]:
                continue
            base = dual[node]
            for edge in graph[node]:
                if cap[edge] > 0:
                    head = to[edge]
                    reach = distance + cost[edge] + base - dual[head]
                    if reach < dist[head]:
                        dist[head] = reach
                        heappush(heap, (reach, head))
        if dist[sink] >= INFINITY:
            break
        for node in range(size):
            if dist[node] < INFINITY:
                dual[node] += dist[node]
        price = dual[sink]
        while True:
            level = [-1] * size
            level[source] = 0
            order = [source]
            head = 0
            while head < len(order):
                node = order[head]
                head += 1
                depth = level[node] + 1
                base = dual[node]
                for edge in graph[node]:
                    if cap[edge] > 0:
                        other = to[edge]
                        if level[other] < 0 and cost[edge] + base - dual[other] == 0:
                            level[other] = depth
                            order.append(other)
            if level[sink] < 0:
                break
            cursor = [0] * size
            while True:
                pushed = _augment_path(graph, to, cap, cost, dual, level, cursor,
                                       source, sink, INFINITY)
                if not pushed:
                    break
                units += pushed
                spent += pushed * price
    return units, spent


def _dead(nodes, paths):
    """Nodes whose own capacity, or some ancestor capacity, is zero."""
    return {name: any(nodes[step]['capacity'] <= 0 for step in path)
            for name, path in paths.items()}


def _slack(nodes, paths, load):
    """True when no node capacity can bind: ``cap(v)`` covers its subtree load."""
    totals = {}
    for name, weight in load.items():
        if weight <= 0:
            continue
        for step in paths[name]:
            totals[step] = totals.get(step, 0) + weight
    for name, total in totals.items():
        if nodes[name]['capacity'] < total:
            return False
    return True


def _augment_slot(start, usable, match):
    """Kuhn augmenting path adding one unit at offer ``start``; True on success."""
    seen_request = set()
    seen_offer = {start}
    parent = {}
    through = {}
    stack = [start]
    while stack:
        offer = stack.pop()
        for name in usable[offer][4]:
            if name in seen_request:
                continue
            seen_request.add(name)
            parent[name] = offer
            current = match.get(name)
            if current is None:
                while name is not None:
                    holder = parent[name]
                    previous = through.get(holder)
                    match[name] = holder
                    name = previous
                return True
            if current in seen_offer:
                continue
            seen_offer.add(current)
            through[current] = name
            stack.append(current)
    return False


def _greedy(usable):
    """Minimum-cost maximum matching when only offer capacities bind."""
    match = {}
    used = {}
    for offer in sorted(range(len(usable)), key=lambda i: (usable[i][1], usable[i][0])):
        capacity = usable[offer][3]
        taken = 0
        while taken < capacity and _augment_slot(offer, usable, match):
            taken += 1
        if taken:
            used[offer] = taken
    cost = 0
    pairs = []
    for name, offer in match.items():
        pairs.append((name, usable[offer][0]))
        cost += usable[offer][1]
    return pairs, cost


def _flow(usable, neighbours, requests, request_nodes, live_requests,
          offer_nodes, live_offers):
    """General min-cost flow route honouring binding quota forests."""
    blocks = {}
    for name in sorted(neighbours):
        key = (requests[name]['group'], tuple(neighbours[name]))
        block = blocks.get(key)
        if block is None:
            blocks[key] = [name]
        else:
            block.append(name)
    members = [sorted(names) for names in blocks.values()]
    request_slot = {name: 1 + index for index, name in enumerate(live_requests)}
    block_base = 1 + len(live_requests)
    offer_base = block_base + len(members)
    offer_slot = {name: offer_base + index for index, name in enumerate(live_offers)}
    sink = offer_base + len(usable) + len(live_offers)
    net = Network(sink + 1)
    for name in live_requests:
        parent = request_nodes[name]['parent']
        node = request_slot[name]
        if parent is None:
            net.add(0, node, request_nodes[name]['capacity'], 0)
        else:
            net.add(request_slot[parent], node, request_nodes[name]['capacity'], 0)
    for name in live_offers:
        parent = offer_nodes[name]['parent']
        node = offer_slot[name]
        if parent is None:
            net.add(node, sink, offer_nodes[name]['capacity'], 0)
        else:
            net.add(node, offer_slot[parent], offer_nodes[name]['capacity'], 0)
    arcs = []
    for index, names in enumerate(members):
        node = block_base + index
        net.add(request_slot[requests[names[0]]['group']], node, len(names), 0)
        arcs.append([])
    for index, item in enumerate(usable):
        net.add(offer_base + index, offer_slot[item[2]], item[3], 0)
    for index, names in enumerate(members):
        node = block_base + index
        width = len(names)
        for offer_index in neighbours[names[0]]:
            capacity = usable[offer_index][3]
            edge = net.add(node, offer_base + offer_index,
                           width if width < capacity else capacity,
                           usable[offer_index][1])
            arcs[index].append((edge, offer_index, net.cap[edge]))
    units, spent = min_cost_flow(net, 0, sink)
    cap = net.cap
    pairs = []
    for index, names in enumerate(members):
        taken = []
        for edge, offer_index, capacity in arcs[index]:
            used = capacity - cap[edge]
            if used > 0:
                taken.extend([usable[offer_index][0]] * used)
        for name, offer in zip(names, taken):
            pairs.append((name, offer))
    return pairs, spent


def solve(context, active):
    """Optimal follow-up plan plus its probe-script certificate."""
    requests = context['requests']
    offers = context['offers']
    leases = context['leases']
    kinds = context['services']
    request_nodes = context['request_quotas']
    request_paths = context['request_paths']
    offer_nodes = context['offer_quotas']
    offer_paths = context['offer_paths']
    request_dead = _dead(request_nodes, request_paths)
    offer_dead = _dead(offer_nodes, offer_paths)

    usable = []
    for name in sorted(offers):
        offer = offers[name]
        capacity = offer['capacity']
        if capacity <= 0 or offer_dead.get(offer['group'], False):
            continue
        network = offer['network']
        lowest = int(network.network_address)
        highest = int(network.broadcast_address)
        moment = offer['time']
        service = offer['service']
        listed = []
        for request in offer['requests']:
            if not active.get(request, False):
                continue
            row = requests[request]
            if row['service'] != service or request_dead.get(row['group'], False):
                continue
            if row['at'] > moment or moment >= leases[row['lease']]['end']:
                continue
            target = row['address']
            if target < lowest or target > highest:
                continue
            listed.append(request)
        if listed:
            usable.append((name, offer['cost'], offer['group'], capacity, listed))

    neighbours = {}
    for index, item in enumerate(usable):
        for request in item[4]:
            bucket = neighbours.get(request)
            if bucket is None:
                neighbours[request] = [index]
            else:
                bucket.append(index)

    if usable and neighbours:
        request_load = {}
        for name in neighbours:
            group = requests[name]['group']
            request_load[group] = request_load.get(group, 0) + 1
        offer_load = {}
        for item in usable:
            offer_load[item[2]] = offer_load.get(item[2], 0) + item[3]
        ceiling = len(neighbours)
        if all(weight >= ceiling for weight in offer_load.values()):
            offer_load = {}
        else:
            offer_load = {name: min(weight, ceiling) for name, weight in offer_load.items()}
        if (_slack(request_nodes, request_paths, request_load)
                and _slack(offer_nodes, offer_paths, offer_load)):
            pairs, spent = _greedy(usable)
        else:
            live_requests = [name for name in request_nodes if not request_dead[name]]
            live_offers = [name for name in offer_nodes if not offer_dead[name]]
            pairs, spent = _flow(usable, neighbours, requests, request_nodes,
                                 live_requests, offer_nodes, live_offers)
    else:
        pairs = []
        spent = 0

    pairs.sort()
    assignments = []
    for name, offer in pairs:
        send, finish = CERTIFICATES[kinds[requests[name]['service']]]
        assignments.append({'request': name, 'offer': offer,
                            'send': send, 'finish': finish})
    return {'resolved': len(assignments), 'cost': spent, 'assignments': assignments}
PYEOF
